oxy_webhelp_navlinks = {"recover_gws_data-d39536e44306":{"topics":[{"title":"Recover Google Drive data","shortdesc":"<p class=\"shortdesc\">After <span class=\"ph\">RSC<\/span> protects your Google Drive workloads, you can recover         entire drives, or specific files and folders.<\/p>","href":"gws\/gdrive_recover_data.html","attributes":{"data-id":"gdrive_recover_data"},"menu":{"hasChildren":false},"tocID":"gdrive_recover_data-d39536e44320","next":"gdrive_recover_data-d39536e44320"},{"title":"Recover Gmail data","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enables you to recover emails, calendar events, and contacts         from a point-in-time snapshot of a protected Google account.<\/p>","href":"gws\/gmail_recover_data.html","attributes":{"data-id":"gmail_recover_data"},"menu":{"hasChildren":false},"tocID":"gmail_recover_data-d39536e44395","next":"gmail_recover_data-d39536e44395"},{"title":"Google groups recovery","shortdesc":"<p class=\"shortdesc\">You can restore Google groups from a snapshot to recover a group that was deleted, or         to roll back changes to the settings, members, and roles of a group.<\/p>","href":"gws\/gws_groups_recovery.html","attributes":{"data-id":"gws_groups_recovery"},"menu":{"hasChildren":false},"tocID":"gws_groups_recovery-d39536e44561","next":"gws_groups_recovery-d39536e44561"},{"title":"Google Workspace mass recovery","shortdesc":"<p class=\"shortdesc\">Mass recovery restores Google Drive data along with Gmail, Calendar, and Contacts         data from a point-in-time snapshot. Depending on the workload, mass recovery restores data         for multiple users, multiple shared drives, specific organizational units,         Google         groups, or the entire Google Workspace application.<\/p>","href":"gws\/gws_mass_recovery.html","attributes":{"data-id":"gws_mass_recovery"},"menu":{"hasChildren":false},"tocID":"gws_mass_recovery-d39536e44597","next":"gws_mass_recovery-d39536e44597"},{"title":"Google Workspace self-service recovery","shortdesc":"<p class=\"shortdesc\">Self-service recovery enables Google Workspace users to search for and recover their         own data without assistance from an administrator.<\/p>","href":"gws\/gws_self_service_recovery.html","attributes":{"data-id":"gws_self_service_recovery"},"menu":{"hasChildren":false},"tocID":"gws_self_service_recovery-d39536e44718","next":"gws_self_service_recovery-d39536e44718"},{"title":"Google Workspace data export","shortdesc":"<p class=\"shortdesc\">You can export Google Workspace data from a point-in-time snapshot as a downloadable         ZIP file.<\/p>","href":"gws\/gws_data_export.html","attributes":{"data-id":"gws_data_export"},"menu":{"hasChildren":false},"tocID":"gws_data_export-d39536e44762","next":"gws_data_export-d39536e44762"},{"title":"Skipped items during Google Workspace backup","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> occasionally skips backing up some Google Workspace items due to         Google API errors or, in rare cases, internal errors.<\/p>","href":"gws\/gws_skipped_items_backup.html","attributes":{"data-id":"gws_skipped_items_backup"},"menu":{"hasChildren":false},"tocID":"gws_skipped_items_backup-d39536e44795","topics":[]}]}};